28	std::set<QString> SSA3000XDriver::GetAvailableDevices()
29	{
30	    std::set<QString> ret;
31	
32	    // attempt to establish a connection to check if the device is available and extract the serial number
33	    detectedDevices.clear();
34	    auto sock = QTcpSocket();
35	    for(auto address : getSearchAddresses()) {
36	        sock.connectToHost(address, 5024);
37	        if(sock.waitForConnected(50)) {
38	           // connection successful
39	            sock.waitForReadyRead(100);
40	            auto line = QString(sock.readLine());
41	            if(line.startsWith("Welcome to the SCPI instrument 'Siglent SSA3")) {
42	                // throw away command prompt ">>"
43	                sock.readLine();
44	                // looks like we are connected to the correct instrument, request serial number
45	                sock.write("*IDN?\r\n");
46	                sock.waitForReadyRead(100);
47	                sock.read(1);
48	                sock.waitForReadyRead(100);
49	                line = QString(sock.readLine());
50	                auto fields = line.split(",");
51	                if(fields.size() == 4) {
52	                    detectedDevices[fields[2]] = address;
53	                    ret.insert(fields[2]);
54	                }
55	            }
56	            sock.disconnect();
57	        }
58	    }
59	    return ret;
60	}
61	
62	bool SSA3000XDriver::connectTo(QString serial)
63	{
64	    if(connected) {
65	        disconnect();
66	    }
67	
68	    // check if this device is actually available
69	    QHostAddress address;
70	    bool available = false;
71	    for(auto d : detectedDevices) {
72	        if(d.first == serial) {
73	            address = d.second;
74	            available = true;
75	            break;
76	        }
77	    }
78	    if(!available) {
79	        // no location information about this device available
80	        return false;
81	    }
82	
83	    dataSocket.connectToHost(address, 5025);
84	
85	    // check if connection succeeds
86	    if(!dataSocket.waitForConnected(1000)) {
87	        // socket failed
88	        dataSocket.close();
89	        InformationBox::ShowError("Error", "TCP connection timed out");
90	        return false;
91	    }
92	
93	    connect(&dataSocket, qOverload<QAbstractSocket::SocketError>(&QTcpSocket::errorOccurred), this, &SSA3000XDriver::ConnectionLost, Qt::QueuedConnection);
94	
95	    // grab model information
96	    dataSocket.write("*IDN?\r\n");
97	    dataSocket.waitForReadyRead(100);
98	    auto line = QString(dataSocket.readLine());
99	    auto fields = line.split(",");
100	    if(fields.size() != 4) {
101	        dataSocket.close();
102	        InformationBox::ShowError("Error", "Invalid *IDN? response");
103	        return false;
104	    }
105	
106	    this->serial = fields[2];
107	
108	    info = Info();
109	    info.hardware_version = fields[1];
110	    info.firmware_version = fields[3].trimmed();
111	    info.supportedFeatures.insert(DeviceDriver::Feature::SA);
112	    info.supportedFeatures.insert(DeviceDriver::Feature::SATrackingGenerator);
113	    info.supportedFeatures.insert(DeviceDriver::Feature::Generator);
114	//    info.supportedFeatures.insert(DeviceDriver::Feature::ExtRefIn);
115	
116	    double maxFreq = 0;
117	    if(info.hardware_version == "SSA3032X") {
118	        maxFreq = 3200000000;
119	    } else if(info.hardware_version == "SSA3021X") {
120	        maxFreq = 2100000000;
121	    } else {
122	        dataSocket.close();
123	        InformationBox::ShowError("Error", "Invalid hardware version: " + info.hardware_version);
124	        return false;
125	    }
126	
127	    info.Limits.SA.ports = 1;
128	    info.Limits.SA.minFreq = 0;
129	    info.Limits.SA.maxFreq = maxFreq;
130	    info.Limits.SA.minRBW = 1;
131	    info.Limits.SA.maxRBW = 3000000;
132	    info.Limits.SA.mindBm = -20;
133	    info.Limits.SA.maxdBm = 0;
134	    info.Limits.Generator.ports = 1;
135	    info.Limits.Generator.minFreq = 0;
136	    info.Limits.Generator.maxFreq = maxFreq;
137	    info.Limits.Generator.mindBm = -20;
138	    info.Limits.Generator.maxdBm = 0;
139	
140	    connected = true;
141	
142	    // reset to default configuration
143	    dataSocket.write("*RST\r\n");
144	
145	    emit InfoUpdated();
146	
147	    return true;
148	}
