177	{
178	    if(!connected) {
179	        return false;
180	    }
181	    startFreq = s.freqStart;
182	    stopFreq = s.freqStop;
183	
184	    write(":FREQ:STAR "+QString::number(s.freqStart));
185	    write(":FREQ:STOP "+QString::number(s.freqStop));
186	    write(":BWID "+QString::number(s.RBW));
187	    write(":FREQ:STAR "+QString::number(s.freqStart));
188	    write(":FREQ:STAR "+QString::number(s.freqStart));
189	    write(":FREQ:STAR "+QString::number(s.freqStart));
190	
191	    QString windowName = "";
192	    switch(s.window) {
193	    case SASettings::Window::FlatTop:
194	        windowName = "FLATtop";
195	        break;
196	    case SASettings::Window::Hann:
197	        windowName = "HANNing";
198	        break;
