201	        break;
202	    case SASettings::Window::None:
203	    case SASettings::Window::Last:
204	        windowName = "RECTangular";
205	        break;
206	    }
207	    write(":DDEM:FFT:WIND "+windowName);
208	
209	    QString detName = "";
210	    switch(s.detector) {
211	    case SASettings::Detector::Average:
212	        detName = "AVERage";
213	        break;
214	    case SASettings::Detector::Normal:
215	        detName = "NORMAL";
216	        break;
217	    case SASettings::Detector::NPeak:
218	        detName = "NEGative";
219	        break;
220	    case SASettings::Detector::PPeak:
221	    case SASettings::Detector::Last:
222	        detName = "POSitive";
