292	bool CompoundDriver::setVNA(const DeviceDriver::VNASettings &s, std::function<void (bool)> cb)
293	{
294	    if(!supports(Feature::VNA)) {
295	        return false;
296	    }
297	    if(s.excitedPorts.size() == 0) {
298	        return setIdle(cb);
299	    }
300	
301	    setIdle([this](bool){
302	        enableTriggerForwarding();
303	        qDebug() << "Start trigger forwarding";
304	    });
305	
306	    // create port->stage mapping
307	    portStageMapping.clear();
308	    for(unsigned int i=0;i<s.excitedPorts.size();i++) {
309	        portStageMapping[s.excitedPorts[i]] = i;
310	    }
311	
312	    zerospan = (s.freqStart == s.freqStop) && (s.dBmStart == s.dBmStop);
313	    VNApoints = s.points;
314	    // create vector of currently used stimulus ports
315	    std::vector<CompoundDevice::PortMapping> activeMapping;
316	    for(auto p : s.excitedPorts) {
317	        activeMapping.push_back(activeDevice.portMapping[p-1]);
318	    }
319	    // Configure the devices
320	    results.clear();
321	    bool success = true;
322	    for(unsigned int i=0;i<devices.size();i++) {
323	        auto dev = devices[i];
324	        dev->setSynchronization(activeDevice.sync, i == 0);
325	        auto devSetting = s;
326	        // indicate the number of stages
327	        devSetting.excitedPorts = std::vector<int>(s.excitedPorts.size(), 0);
328	        // activate the ports of this specific device at the correct stage
329	        auto p1Stage = CompoundDevice::PortMapping::findActiveStage(activeMapping, i, 0);
330	        if(p1Stage < s.excitedPorts.size()) {
331	            devSetting.excitedPorts[p1Stage] = 1;
332	        }
333	        auto p2Stage = CompoundDevice::PortMapping::findActiveStage(activeMapping, i, 1);
334	        if(p2Stage < s.excitedPorts.size()) {
335	            devSetting.excitedPorts[p2Stage] = 2;
336	        }
337	        success &= devices[i]->setVNA(devSetting, [=](bool success){
338	            if(cb) {
339	                results[devices[i]] = success;
340	                checkIfAllTransmissionsComplete(cb);
341	            }
342	        });
343	    }
344	
345	    lastNonIdleSettings.type = Types::VNA;
346	    lastNonIdleSettings.vna = s;
347	    isIdle = false;
348	
349	    return success;
350	}
