726	void CompoundDriver::datapointReceivecd(LibreVNADriver *dev, Protocol::VNADatapoint<32> *data)
727	{
728	    if(!compoundVNABuffer.count(data->pointNum)) {
729	        compoundVNABuffer[data->pointNum] = std::map<LibreVNADriver*, Protocol::VNADatapoint<32>*>();
730	    }
731	    auto &buf = compoundVNABuffer[data->pointNum];
732	    // create copy of datapoint as it will be deleted by the device driver
733	    buf[dev] = new Protocol::VNADatapoint<32>(*data);
734	    if(buf.size() == devices.size()) {
735	        // Got datapoints from all devices, can create merged VNA result
736	        VNAMeasurement m;
737	        m.pointNum = data->pointNum;
738	        m.Z0 = 50.0;
739	        if(zerospan) {
740	            m.us = data->us;
741	        } else {
742	            m.frequency = data->frequency;
743	            m.dBm = (double) data->cdBm / 100;
744	        }
745	        // assemble data
746	        for(auto map : portStageMapping) {
747	            // map.first is the port (starts at one)
748	            // map.second is the stage at which this port had the stimulus (starts at zero)
749	
750	            // figure out which device had the stimulus for the port...
751	            auto stimulusDev = devices[activeDevice.portMapping[map.first-1].device];
752	            // ...and which device port was used for the stimulus...
753	            auto stimulusDevPort = activeDevice.portMapping[map.first-1].port;
754	            // ...grab the reference receiver data
755	            std::complex<double> ref = buf[stimulusDev]->getValue(map.second, stimulusDevPort, true);
756	
757	            // for all ports of the compound device...
758	            for(unsigned int i=0;i<activeDevice.portMapping.size();i++) {
759	                // ...figure out which physical device and port was used for this input...
760	                auto inputDevice = devices[activeDevice.portMapping[i].device];
761	                // ...and grab the data
762	                auto inputPort = activeDevice.portMapping[i].port;
763	                std::complex<double> input = buf[inputDevice]->getValue(map.second, inputPort, false);
764	                if(!std::isnan(ref.real()) && !std::isnan(input.real())) {
765	                    // got both required measurements
766	                    QString name = "S"+QString::number(i+1)+QString::number(map.first);
767	                    auto S = input / ref;
768	                    if(!preservePhase && (inputDevice != stimulusDev)) {
769	                        // can't use phase information when measuring across devices
770	                        S = abs(S);
771	                    }
772	                    m.measurements[name] = S;
773	                }
774	
775	                if(captureRawReceiverValues) {
776	                    QString name = "RawPort"+QString::number(inputPort+1)+"Stage"+QString::number(map.second);
777	                    m.measurements[name] = input;
778	                    name = "RawPort"+QString::number(inputPort+1)+"Stage"+QString::number(map.second)+"Ref";
779	                    m.measurements[name] = buf[inputDevice]->getValue(map.second, inputPort, true);
780	                }
781	            }
782	        }
783	
784	        emit VNAmeasurementReceived(m);
785	
786	        // Clear this and all (incomplete) older datapoint buffers
787	        int pointNum = data->pointNum;
788	        while(compoundVNABuffer.count(pointNum)) {
789	            auto &buf = compoundVNABuffer[pointNum];
790	            for(auto d : buf) {
791	                delete d.second;
792	            }
793	            compoundVNABuffer.erase(pointNum);
794	            // move on to previous point
795	            if(pointNum > 0) {
796	                pointNum--;
797	            } else {
798	                pointNum = VNApoints - 1;
799	            }
800	        }
801	    }
802	}
